// src/main/java/com/example/ticketdesk/request/WorkRequestDtos.java
// API 입출력 DTO 를 record 로 모아 둡니다. 도메인 객체를 그대로 내보내지 않습니다.
package com.example.ticketdesk.request;

import jakarta.validation.constraints.FutureOrPresent;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;
import java.time.Instant;
import java.time.LocalDate;

public final class WorkRequestDtos {

    private WorkRequestDtos() { }

    /** 등록 입력 — 기본 트랙의 zod 스키마와 같은 규칙 */
    public record CreateRequest(
            @NotBlank(message = "제목을 입력하세요")
            @Size(min = 5, max = 100, message = "제목은 5~100자로 입력하세요")
            String title,

            @NotBlank(message = "내용을 입력하세요")
            @Size(min = 10, max = 4000, message = "내용은 10~4000자로 입력하세요")
            String body,

            @FutureOrPresent(message = "마감일은 오늘 이후여야 합니다")
            LocalDate dueDate) { }

    /** 상태 변경 입력 */
    public record StatusChange(@NotNull(message = "상태를 선택하세요") WorkRequest.Status status) { }

    /** 응답 — 필요한 필드만 골라 내보냅니다 */
    public record Response(
            Long id, String title, String body, LocalDate dueDate,
            WorkRequest.Status status, WorkRequest.Category category,
            WorkRequest.Priority priority, String summary,
            String requesterId, Instant createdAt) {

        public static Response from(WorkRequest w) {
            return new Response(w.getId(), w.getTitle(), w.getBody(), w.getDueDate(),
                    w.getStatus(), w.getCategory(), w.getPriority(), w.getSummary(),
                    w.getRequesterId(), w.getCreatedAt());
        }
    }
}

// lib/requests.ts — 업무 요청의 타입 · 입력 스키마 · (오늘만) 메모리 저장소
// 세션 15에서 저장소 부분을 Supabase 로 바꾸고, 타입과 스키마는 그대로 씁니다.
import { z } from "zod";

export const STATUSES = ["RECEIVED", "IN_PROGRESS", "DONE"] as const;
export const CATEGORIES = ["DATA_EXTRACT", "BATCH_ISSUE", "ACCESS", "REPORT", "ETC"] as const;
export const PRIORITIES = ["LOW", "MEDIUM", "HIGH"] as const;

export type Status = (typeof STATUSES)[number];
export type Category = (typeof CATEGORIES)[number];
export type Priority = (typeof PRIORITIES)[number];

export type WorkRequest = {
  id: string;
  title: string;
  body: string;
  dueDate: string | null;      // YYYY-MM-DD
  status: Status;
  category: Category | null;   // 세션 15에서 AI 가 채움
  priority: Priority | null;
  summary: string | null;
  requesterId: string;
  createdAt: string;           // ISO 8601
};

const today = () => new Date().toISOString().slice(0, 10);

// 등록 입력: 화면이 무엇을 보내든 서버에서 다시 검증합니다
export const createRequestSchema = z.object({
  title: z.string().trim().min(5, "제목은 5자 이상 입력하세요").max(100, "제목은 100자 이하로 입력하세요"),
  body: z.string().trim().min(10, "내용은 10자 이상 입력하세요").max(4000, "내용은 4000자 이하로 입력하세요"),
  dueDate: z.iso.date("날짜 형식은 YYYY-MM-DD 입니다")
    .refine((d) => d >= today(), "마감일은 오늘 이후여야 합니다")
    .optional(),
});
export type CreateRequestInput = z.infer<typeof createRequestSchema>;

export const statusChangeSchema = z.object({ status: z.enum(STATUSES) });
export const listQuerySchema = z.object({ status: z.enum(STATUSES).optional() });

// ── 메모리 저장소 (개발 서버가 다시 읽어도 유지되도록 globalThis 에 둡니다)
const g = globalThis as unknown as { __requests?: Map<string, WorkRequest> };
const store = (g.__requests ??= new Map<string, WorkRequest>());

export function listRequests(status?: Status): WorkRequest[] {
  return [...store.values()]
    .filter((r) => !status || r.status === status)
    .sort((a, b) => b.createdAt.localeCompare(a.createdAt));
}

export function getRequest(id: string): WorkRequest | undefined {
  return store.get(id);
}

export function createRequest(input: CreateRequestInput, requesterId: string): WorkRequest {
  const item: WorkRequest = {
    id: crypto.randomUUID(),
    title: input.title,
    body: input.body,
    dueDate: input.dueDate ?? null,
    status: "RECEIVED",
    category: null,
    priority: null,
    summary: null,
    requesterId,
    createdAt: new Date().toISOString(),
  };
  store.set(item.id, item);
  return item;
}

export function updateStatus(id: string, status: Status): WorkRequest | undefined {
  const item = store.get(id);
  if (!item) return undefined;
  const updated = { ...item, status };
  store.set(id, updated);
  return updated;
}

// app/api/requests/route.ts — 목록 조회(GET)와 등록(POST)
import type { NextRequest } from "next/server";
import { z } from "zod";
import { createRequest, createRequestSchema, listQuerySchema, listRequests } from "@/lib/requests";

export async function GET(request: NextRequest) {
  const parsed = listQuerySchema.safeParse({
    status: request.nextUrl.searchParams.get("status") ?? undefined,
  });
  if (!parsed.success) {
    return Response.json(
      { message: "조회 조건을 확인하세요", errors: z.flattenError(parsed.error).fieldErrors },
      { status: 400 },
    );
  }
  return Response.json(listRequests(parsed.data.status));
}

export async function POST(request: NextRequest) {
  let json: unknown;
  try {
    json = await request.json();
  } catch {
    return Response.json({ message: "JSON 형식이 아닙니다" }, { status: 400 });
  }

  const parsed = createRequestSchema.safeParse(json);
  if (!parsed.success) {
    return Response.json(
      { message: "입력값을 확인하세요", errors: z.flattenError(parsed.error).fieldErrors },
      { status: 400 },
    );
  }

  // 로그인은 세션 15에서 붙입니다. 오늘은 고정 사용자로 기록합니다.
  const created = createRequest(parsed.data, "demo-user");
  return Response.json(created, {
    status: 201,
    headers: { Location: `/api/requests/${created.id}` },
  });
}

// app/requests/request-form.tsx — 등록 폼 (클라이언트 컴포넌트)
// 화면은 API 만 부릅니다. 같은 API 를 n8n 이나 다른 시스템도 그대로 씁니다.
"use client";

import { useRouter } from "next/navigation";
import { useState, type FormEvent } from "react";

type FieldErrors = Record<string, string[] | undefined>;

export function RequestForm() {
  const router = useRouter();
  const [errors, setErrors] = useState<FieldErrors>({});
  const [message, setMessage] = useState("");
  const [pending, setPending] = useState(false);

  async function onSubmit(e: FormEvent<HTMLFormElement>) {
    e.preventDefault();
    const form = e.currentTarget;
    const data = Object.fromEntries(new FormData(form));
    if (!data.dueDate) delete data.dueDate; // 빈 날짜는 보내지 않음

    setPending(true);
    const res = await fetch("/api/requests", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(data),
    });
    setPending(false);

    if (res.status === 400) {
      const body = await res.json();
      setErrors(body.errors ?? {});
      setMessage(body.message ?? "입력값을 확인하세요");
      return;
    }
    if (!res.ok) {
      setMessage("저장하지 못했습니다. 잠시 후 다시 시도하세요.");
      return;
    }
    form.reset();
    setErrors({});
    setMessage("접수되었습니다.");
    router.refresh(); // 서버 컴포넌트 목록 다시 그리기
  }

  return (
    <form onSubmit={onSubmit} style={{ display: "grid", gap: 8 }}>
      <label>제목 <input name="title" required minLength={5} maxLength={100} /></label>
      {errors.title && <small style={{ color: "crimson" }}>{errors.title.join(", ")}</small>}

      <label>내용 <textarea name="body" rows={5} required minLength={10} maxLength={4000} /></label>
      {errors.body && <small style={{ color: "crimson" }}>{errors.body.join(", ")}</small>}

      <label>마감일 <input name="dueDate" type="date" /></label>
      {errors.dueDate && <small style={{ color: "crimson" }}>{errors.dueDate.join(", ")}</small>}

      <button type="submit" disabled={pending}>{pending ? "저장 중…" : "접수"}</button>
      {message && <p role="status">{message}</p>}
    </form>
  );
}

// src/main/java/com/example/ticketdesk/request/WorkRequest.java
// 업무 요청 도메인. 세션 15에서 이 클래스에 JPA 어노테이션을 붙여 Oracle 테이블과 연결합니다.
package com.example.ticketdesk.request;

import java.time.Instant;
import java.time.LocalDate;

public class WorkRequest {

    public enum Status { RECEIVED, IN_PROGRESS, DONE }
    public enum Category { DATA_EXTRACT, BATCH_ISSUE, ACCESS, REPORT, ETC }
    public enum Priority { LOW, MEDIUM, HIGH }

    private Long id;
    private String title;
    private String body;
    private LocalDate dueDate;
    private Status status = Status.RECEIVED;
    private Category category;     // 세션 15에서 AI 가 채움
    private Priority priority;
    private String summary;
    private String requesterId;
    private Instant createdAt = Instant.now();

    protected WorkRequest() { }

    public WorkRequest(String title, String body, LocalDate dueDate, String requesterId) {
        this.title = title;
        this.body = body;
        this.dueDate = dueDate;
        this.requesterId = requesterId;
    }

    public void changeStatus(Status next) { this.status = next; }

    public void applyAnalysis(String summary, Category category, Priority priority) {
        this.summary = summary;
        this.category = category;
        this.priority = priority;
    }

    void assignId(Long id) { this.id = id; }   // 메모리 저장소 전용 (세션 15에서 삭제)

    public Long getId() { return id; }
    public String getTitle() { return title; }
    public String getBody() { return body; }
    public LocalDate getDueDate() { return dueDate; }
    public Status getStatus() { return status; }
    public Category getCategory() { return category; }
    public Priority getPriority() { return priority; }
    public String getSummary() { return summary; }
    public String getRequesterId() { return requesterId; }
    public Instant getCreatedAt() { return createdAt; }
}

